import{_ as d}from"./chunks/tier-kits.CX-RPaZj.js";import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.CN568Poi.js";const u=JSON.parse('{"title":"采集与处理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/collection.md","filePath":"zh/collection.md","lastUpdated":1795431209000}'),s={name:"zh/collection.md"};function n(c,t,i,h,l,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="采集与处理" tabindex="-1">采集与处理 <a class="header-anchor" href="#采集与处理" aria-label="Permalink to &quot;采集与处理&quot;">​</a></h1><p align="center"><img src="'+d+'" alt="按层级划分的采集设备" width="100%"><br><sub>三套设备：L1 头环；L2 增加肌电臂环；L3 增加脑电、腕部相机、眼动仪、手套与 tracker。图源：技术报告。</sub></p><h2 id="硬件配置" tabindex="-1">硬件配置 <a class="header-anchor" href="#硬件配置" aria-label="Permalink to &quot;硬件配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>数据流</th><th>设备（示例）</th><th>原生分辨率 / 通道</th><th>频率</th><th>单位</th></tr></thead><tbody><tr><td>L1</td><td>头部 RGB</td><td>14 款第三方头环、13 家厂商、2–6 目</td><td>512×512–3840×1200</td><td>20–60 fps</td><td>RGB</td></tr><tr><td>L2</td><td>头部 RGB</td><td>四目头环，前向立体对同步</td><td>1920×1200</td><td>30 fps</td><td>RGB</td></tr><tr><td>L2/L3</td><td>腕部 RGB</td><td>JIERUIWEITONG FH868</td><td>640×480（部分 L2 发布为 1920×1080）</td><td>30 fps</td><td>RGB</td></tr><tr><td>L3</td><td>眼动场景相机</td><td>Pupil Labs Neon</td><td>1600×1200</td><td>30 fps</td><td>RGB</td></tr><tr><td>L3</td><td>第三人称</td><td>Intel RealSense D455f</td><td>640×480</td><td>30 fps</td><td>RGB-D</td></tr><tr><td>L3</td><td>注视</td><td>Pupil Labs Neon</td><td>x, y 像素</td><td>200 Hz</td><td>px</td></tr><tr><td>L3</td><td>头/腕位姿</td><td>HTC VIVE Tracker 3.0 ×3</td><td>同一坐标系下的 6-DoF</td><td>设备约 800 Hz</td><td>mm / deg</td></tr><tr><td>L3</td><td>手指运动学</td><td>MANUS Metaglove Pro</td><td>每手 20 个关节</td><td>设备约 800 Hz</td><td>deg</td></tr><tr><td>L2/L3</td><td>表面肌电</td><td>WLEMGUV2A ×2</td><td>每臂 8 通道</td><td>2 kHz</td><td>mV</td></tr><tr><td>L3</td><td>脑电（受控）</td><td>Neuroscan SynAmps2</td><td>128 通道</td><td>1 kHz</td><td>µV</td></tr><tr><td>L3</td><td>脑电（开放）</td><td>BrainCo BCIGo</td><td>32/8 通道</td><td>250 Hz</td><td>µV</td></tr></tbody></table><p>发布流可能被降采样，实际形状以 <code>meta/info.json</code> 为准。设备之间不做菊花链：单一主机接收所有数据流并记录到达偏移，因此每台设备保留自己的时钟和原生频率。并口盒把阶段/run 切换写入脑电放大器。</p><h2 id="开放与受控" tabindex="-1">开放与受控 <a class="header-anchor" href="#开放与受控" aria-label="Permalink to &quot;开放与受控&quot;">​</a></h2><p>L1 和 L2 在<strong>开放环境</strong>采集：可穿戴设备、头环计算机、自由走动。L2 和 L3 用任务单固定物体摆放和步骤顺序。L3 还有<strong>受控环境</strong>：固定桌面、稳定光照、有时限 session，以满足高密度脑电、眼动和动捕对静止姿态的要求。</p><p>受控 session 分两段。<strong>运动想象（imagery）</strong>：屏幕变蓝，操作者坐直不动，在脑中预演任务，只记录脑电和注视。<strong>执行（execution）</strong>：屏幕变绿，同一任务真正执行，所有模态同时记录。<code>run start</code>、<code>imagine</code>、<code>execute</code>、<code>run end</code> 等标记写入记录，因此两段可以按同一时间基切出来。</p><h2 id="从原始信号到发布表" tabindex="-1">从原始信号到发布表 <a class="header-anchor" href="#从原始信号到发布表" aria-label="Permalink to &quot;从原始信号到发布表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>发布什么</th></tr></thead><tbody><tr><td>同步与标定</td><td>样本相对 episode 起点打时间戳；记录到达偏移；相机、tracker 与眼动仪按 session 标定。</td><td>时间戳、内参、畸变、校正参数与 tracker 变换。</td></tr><tr><td>几何与运动</td><td>深度由同步立体对经 FoundationStereo 得到；逐帧投影点云；手部在重叠视频窗口上重建并锚定到深度。</td><td>深度、点云、头/腕/胸位姿与手指运动学。</td></tr><tr><td>注视</td><td>受控 L3 由眼动仪以 200 Hz 实测；其余由视频模型以 30 Hz 预测。</td><td><code>eye_gaze</code> 与 <code>eye_gaze_predict</code>。</td></tr><tr><td>肌电</td><td>零相位 20–450 Hz 带通与 50 Hz 梳状陷波；保留原始与去噪轨迹。</td><td><code>*_emg_raw</code> / <code>*_emg_denoise</code>。</td></tr><tr><td>脑电</td><td>去均值、0.5–100 Hz 带通、50 Hz 陷波、坏导联检测、ICA、插值与平均参考。</td><td>原始与清洗后的脑电表。</td></tr><tr><td>标注与质检</td><td>Argus + Qwen 生成步骤标注，人工审核；每条 session 写完后逐流检查。</td><td>结构化标注 JSON、<code>qc_reports.jsonl</code>；失败 session 重采。</td></tr></tbody></table><h2 id="隐私与许可" tabindex="-1">隐私与许可 <a class="header-anchor" href="#隐私与许可" aria-label="Permalink to &quot;隐私与许可&quot;">​</a></h2><p>所有参与者签署书面知情同意，并可随时退出。发布 episode 已去标识化，所有视角中的人脸都做了模糊处理。数据以 CC BY-NC 4.0 发布，代码使用 Apache-2.0。</p>',12)])])}const L=e(s,[["render",n]]);export{u as __pageData,L as default};
